k = input(7, "K Neighbors", 1, 20, 1)
featLook = input(20, "Feature Lookback", 5, 60, 1)
normLen = input(20, "Normalization Length", 5, 60, 1)
marginThresh = input(0.43, "Margin Threshold", 0.1, 1.0, 0.01)
disThresh = input(0.5, "Disagreement Threshold", 0.1, 1.0, 0.01)
markerSize = input(1.0, "Marker Size", 0.2, 3.0, 0.1)

// ─── Raw OHLC features ───
f1raw = close - open
f2raw = high - low
f3raw = close - close[1]

// Normalization by max absolute value over last 20 bars (mean-dev free, pure max-norm)
max1 = highest(abs(f1raw), 20)
max2 = highest(abs(f2raw), 20)
max3 = highest(abs(f3raw), 20)
den1 = max1 + 0.000000001
den2 = max2 + 0.000000001
den3 = max3 + 0.000000001
n1 = f1raw / den1
n2 = f2raw / den2
n3 = f3raw / den3

// ─── Euclidean distances to past 20 vectors V1..V20 ───
d01 = sqrt((n1 - n1[1]) * (n1 - n1[1]) + (n2 - n2[1]) * (n2 - n2[1]) + (n3 - n3[1]) * (n3 - n3[1]))
d02 = sqrt((n1 - n1[2]) * (n1 - n1[2]) + (n2 - n2[2]) * (n2 - n2[2]) + (n3 - n3[2]) * (n3 - n3[2]))
d03 = sqrt((n1 - n1[3]) * (n1 - n1[3]) + (n2 - n2[3]) * (n2 - n2[3]) + (n3 - n3[3]) * (n3 - n3[3]))
d04 = sqrt((n1 - n1[4]) * (n1 - n1[4]) + (n2 - n2[4]) * (n2 - n2[4]) + (n3 - n3[4]) * (n3 - n3[4]))
d05 = sqrt((n1 - n1[5]) * (n1 - n1[5]) + (n2 - n2[5]) * (n2 - n2[5]) + (n3 - n3[5]) * (n3 - n3[5]))
d06 = sqrt((n1 - n1[6]) * (n1 - n1[6]) + (n2 - n2[6]) * (n2 - n2[6]) + (n3 - n3[6]) * (n3 - n3[6]))
d07 = sqrt((n1 - n1[7]) * (n1 - n1[7]) + (n2 - n2[7]) * (n2 - n2[7]) + (n3 - n3[7]) * (n3 - n3[7]))
d08 = sqrt((n1 - n1[8]) * (n1 - n1[8]) + (n2 - n2[8]) * (n2 - n2[8]) + (n3 - n3[8]) * (n3 - n3[8]))
d09 = sqrt((n1 - n1[9]) * (n1 - n1[9]) + (n2 - n2[9]) * (n2 - n2[9]) + (n3 - n3[9]) * (n3 - n3[9]))
d10 = sqrt((n1 - n1[10]) * (n1 - n1[10]) + (n2 - n2[10]) * (n2 - n2[10]) + (n3 - n3[10]) * (n3 - n3[10]))
d11 = sqrt((n1 - n1[11]) * (n1 - n1[11]) + (n2 - n2[11]) * (n2 - n2[11]) + (n3 - n3[11]) * (n3 - n3[11]))
d12 = sqrt((n1 - n1[12]) * (n1 - n1[12]) + (n2 - n2[12]) * (n2 - n2[12]) + (n3 - n3[12]) * (n3 - n3[12]))
d13 = sqrt((n1 - n1[13]) * (n1 - n1[13]) + (n2 - n2[13]) * (n2 - n2[13]) + (n3 - n3[13]) * (n3 - n3[13]))
d14 = sqrt((n1 - n1[14]) * (n1 - n1[14]) + (n2 - n2[14]) * (n2 - n2[14]) + (n3 - n3[14]) * (n3 - n3[14]))
d15 = sqrt((n1 - n1[15]) * (n1 - n1[15]) + (n2 - n2[15]) * (n2 - n2[15]) + (n3 - n3[15]) * (n3 - n3[15]))
d16 = sqrt((n1 - n1[16]) * (n1 - n1[16]) + (n2 - n2[16]) * (n2 - n2[16]) + (n3 - n3[16]) * (n3 - n3[16]))
d17 = sqrt((n1 - n1[17]) * (n1 - n1[17]) + (n2 - n2[17]) * (n2 - n2[17]) + (n3 - n3[17]) * (n3 - n3[17]))
d18 = sqrt((n1 - n1[18]) * (n1 - n1[18]) + (n2 - n2[18]) * (n2 - n2[18]) + (n3 - n3[18]) * (n3 - n3[18]))
d19 = sqrt((n1 - n1[19]) * (n1 - n1[19]) + (n2 - n2[19]) * (n2 - n2[19]) + (n3 - n3[19]) * (n3 - n3[19]))
d20 = sqrt((n1 - n1[20]) * (n1 - n1[20]) + (n2 - n2[20]) * (n2 - n2[20]) + (n3 - n3[20]) * (n3 - n3[20]))

// ─── Known next-bar direction labels D for V1..V20 (+1 / -1) ───
dir01 = 0 - 1
if close > close[1] { dir01 := 1 }
dir02 = 0 - 1
if close[1] > close[2] { dir02 := 1 }
dir03 = 0 - 1
if close[2] > close[3] { dir03 := 1 }
dir04 = 0 - 1
if close[3] > close[4] { dir04 := 1 }
dir05 = 0 - 1
if close[4] > close[5] { dir05 := 1 }
dir06 = 0 - 1
if close[5] > close[6] { dir06 := 1 }
dir07 = 0 - 1
if close[6] > close[7] { dir07 := 1 }
dir08 = 0 - 1
if close[7] > close[8] { dir08 := 1 }
dir09 = 0 - 1
if close[8] > close[9] { dir09 := 1 }
dir10 = 0 - 1
if close[9] > close[10] { dir10 := 1 }
dir11 = 0 - 1
if close[10] > close[11] { dir11 := 1 }
dir12 = 0 - 1
if close[11] > close[12] { dir12 := 1 }
dir13 = 0 - 1
if close[12] > close[13] { dir13 := 1 }
dir14 = 0 - 1
if close[13] > close[14] { dir14 := 1 }
dir15 = 0 - 1
if close[14] > close[15] { dir15 := 1 }
dir16 = 0 - 1
if close[15] > close[16] { dir16 := 1 }
dir17 = 0 - 1
if close[16] > close[17] { dir17 := 1 }
dir18 = 0 - 1
if close[17] > close[18] { dir18 := 1 }
dir19 = 0 - 1
if close[18] > close[19] { dir19 := 1 }
dir20 = 0 - 1
if close[19] > close[20] { dir20 := 1 }

// ─── Pack into literal lists (independently readable channels source) ───
dists = [d01, d02, d03, d04, d05, d06, d07, d08, d09, d10, d11, d12, d13, d14, d15, d16, d17, d18, d19, d20]
targets = [dir01, dir02, dir03, dir04, dir05, dir06, dir07, dir08, dir09, dir10, dir11, dir12, dir13, dir14, dir15, dir16, dir17, dir18, dir19, dir20]

// ─── k=7 nearest selection (insertion into 7 sorted slots) ───
best0 = 999999.0
best1 = 999999.0
best2 = 999999.0
best3 = 999999.0
best4 = 999999.0
best5 = 999999.0
best6 = 999999.0
bt0 = 0
bt1 = 0
bt2 = 0
bt3 = 0
bt4 = 0
bt5 = 0
bt6 = 0

j = 0
while j < 20 {
    curD = dists[j]
    curT = targets[j]
    if curD < best0 {
        best6 := best5
        bt6 := bt5
        best5 := best4
        bt5 := bt4
        best4 := best3
        bt4 := bt3
        best3 := best2
        bt3 := bt2
        best2 := best1
        bt2 := bt1
        best1 := best0
        bt1 := bt0
        best0 := curD
        bt0 := curT
    } else {
        if curD < best1 {
            best6 := best5
            bt6 := bt5
            best5 := best4
            bt5 := bt4
            best4 := best3
            bt4 := bt3
            best3 := best2
            bt3 := bt2
            best2 := best1
            bt2 := bt1
            best1 := curD
            bt1 := curT
        } else {
            if curD < best2 {
                best6 := best5
                bt6 := bt5
                best5 := best4
                bt5 := bt4
                best4 := best3
                bt4 := bt3
                best3 := best2
                bt3 := bt2
                best2 := curD
                bt2 := curT
            } else {
                if curD < best3 {
                    best6 := best5
                    bt6 := bt5
                    best5 := best4
                    bt5 := bt4
                    best4 := best3
                    bt4 := bt3
                    best3 := curD
                    bt3 := curT
                } else {
                    if curD < best4 {
                        best6 := best5
                        bt6 := bt5
                        best5 := best4
                        bt5 := bt4
                        best4 := curD
                        bt4 := curT
                    } else {
                        if curD < best5 {
                            best6 := best5
                            bt6 := bt5
                            best5 := curD
                            bt5 := curT
                        } else {
                            if curD < best6 {
                                best6 := curD
                                bt6 := curT
                            }
                        }
                    }
                }
            }
        }
    }
    j := j + 1
}

// ─── Vote margin M = (Up - Down) / k ───
upVotes = 0
if bt0 == 1 { upVotes := upVotes + 1 }
if bt1 == 1 { upVotes := upVotes + 1 }
if bt2 == 1 { upVotes := upVotes + 1 }
if bt3 == 1 { upVotes := upVotes + 1 }
if bt4 == 1 { upVotes := upVotes + 1 }
if bt5 == 1 { upVotes := upVotes + 1 }
if bt6 == 1 { upVotes := upVotes + 1 }
kEff = k + 0.0
marginRaw = (upVotes - (7 - upVotes)) / kEff

// ─── Neighbour disagreement G = (std of D + normalized mean dist) / 2 ───
meanD = (best0 + best1 + best2 + best3 + best4 + best5 + best6) / 7.0
voteStd = sqrt(1.0 - marginRaw * marginRaw)
normMean = meanD / (meanD + 1.0)
disRaw = (voteStd + normMean) / 2.0

// Warmup guard: hold flat until 20 bars of history exist
warm = bar_index >= 20
marginVal = 0.0
if warm { marginVal := marginRaw }
disVal = 1.0
if warm { disVal := disRaw }

// 3D dynamic twins (modulated so series vary every bar)
marginDyn = marginVal + close * 0.0000001
disDyn = disVal + close * 0.0000001

// ─── Signal conditions: only when BOTH agree ───
buyState = marginVal > marginThresh and disVal < disThresh
sellState = marginVal < (0 - marginThresh) and disVal < disThresh
buySig = buyState and not buyState[1] and warm
sellSig = sellState and not sellState[1] and warm

// ─── 2D signal markers (events, inside conditionals) ───
if buySig { plotshape(bar_index, low, "Buy", "triangleup", "#22cc88") }
if sellSig { plotshape(bar_index, high, "Sell", "triangledown", "#ff4477") }

// ─── 3D signal markers in SAME pane ───
if buySig { plotshape_3d(bar_index, marginVal, "Buy", "coneup", "#22cc88", 1.0 * markerSize, 0, "separate") }
if sellSig { plotshape_3d(bar_index, marginVal, "Sell", "conedown", "#ff4477", 1.0 * markerSize, 0, "separate") }

// ─── Unconditional 2D rendering LAST ───
plot(marginVal, "Vote Margin M", "#22cc88", 2, "separate")
plot(disVal, "Disagreement G", "#ff9f43", 1, "separate")
hline(0.43, "#22cc8855", "separate")
hline(0.5, "#ff9f4355", "separate")

// ─── 3D form: tall thin spike = crisp, short wide puck = contested ───
barCol = "#22cc88"
if marginVal < 0 { barCol := "#ff4477" }
plot3d(marginDyn, "Margin Columns", "bars3d", barCol, "separate", 0)
plot3d(disDyn, "Disagreement Base", "surface", "#ff9f43", "separate", 1)

// Visible Session Value Terrain Model
// Volume-profile value area engine with 3D terrain + labelled POC rail.

ProfileRows = input(24, "ProfileRows", 12, 48, 1)
ValueAreaPercent = input(70, "ValueAreaPercent", 50, 90, 5)
SessionLengthBars = input(96, "SessionLengthBars", 24, 240, 4)
PocLookback = input(30, "POC Rail Lookback", 5, 100, 1)
markerSize = input(1.0, "Marker Size", 0.2, 3.0, 0.1)

// ─── Session window ──────────────────────────────────────────────
sessHigh = highest(high, SessionLengthBars)
sessLow = lowest(low, SessionLengthBars)
rng = sessHigh - sessLow
if rng <= 0 {
    rng := close * 0.01
}
rowH = rng / ProfileRows

// ─── Row volumes: fresh distribution each bar ────────────────────
rowVol = array()
i = 0
while i < ProfileRows {
    array.push(rowVol, 0.0)
    i := i + 1
}

k = 0
while k < SessionLengthBars {
    bkHigh = high[k]
    bkLow = low[k]
    bkClose = close[k]
    bkVol = volume[k]
    typ = (bkHigh + bkLow + bkClose) / 3
    span = bkHigh - bkLow
    r = 0
    while r < ProfileRows {
        rowBot = sessLow + r * rowH
        rowTop = rowBot + rowH
        add = 0.0
        if span <= 0 {
            if typ >= rowBot and typ < rowTop {
                add := bkVol
            } else {
                if r == ProfileRows - 1 and typ >= rowTop {
                    add := bkVol
                }
            }
        } else {
            top = bkHigh
            if rowTop < top {
                top := rowTop
            }
            bot = bkLow
            if rowBot > bot {
                bot := rowBot
            }
            ov = top - bot
            if ov > 0 {
                add := bkVol * ov / span
            }
        }
        if add > 0 {
            array.set(rowVol, r, array.get(rowVol, r) + add)
        }
        r := r + 1
    }
    k := k + 1
}

totalVol = array.sum(rowVol)

// ─── Point of Control: max-volume row ────────────────────────────
pocRow = 0
pocVol = array.get(rowVol, 0)
i = 1
while i < ProfileRows {
    v = array.get(rowVol, i)
    if v > pocVol {
        pocVol := v
        pocRow := i
    }
    i := i + 1
}
pocPrice = sessLow + (pocRow + 0.5) * rowH

// ─── Value area: sort rows by volume desc, accumulate ─────────────
order = array()
i = 0
while i < ProfileRows {
    array.push(order, i * 1.0)
    i := i + 1
}
a = 0
while a < ProfileRows {
    b = a + 1
    while b < ProfileRows {
        ia = floor(array.get(order, a))
        ib = floor(array.get(order, b))
        va = array.get(rowVol, ia)
        vb = array.get(rowVol, ib)
        if vb > va {
            array.set(order, a, ib * 1.0)
            array.set(order, b, ia * 1.0)
        }
        b := b + 1
    }
    a := a + 1
}
target = totalVol * ValueAreaPercent / 100
accum = 0.0
vaTopRow = pocRow
vaBotRow = pocRow
n = 0
while n < ProfileRows {
    rn = floor(array.get(order, n))
    accum := accum + array.get(rowVol, rn)
    if rn > vaTopRow {
        vaTopRow := rn
    }
    if rn < vaBotRow {
        vaBotRow := rn
    }
    if accum >= target {
        n := ProfileRows
    }
    n := n + 1
}
vah = sessLow + (vaTopRow + 1) * rowH
val = sessLow + vaBotRow * rowH
vaMid = (vah + val) / 2
pocShare = 0.0
if totalVol > 0 {
    pocShare := pocVol / totalVol
}
vaWidth = vah - val
insideVA = close >= val and close <= vah
insidePrev = close[1] >= val[1] and close[1] <= vah[1]
insidePrev2 = close[2] >= val[2] and close[2] <= vah[2]

// ─── Persistent edge state ───────────────────────────────────────
var wasPocRow = -1.0
var pocHold = 0.0

// ─── Signals: price leaving value ────────────────────────────────
buySig = insidePrev and insidePrev2 and close > vah and close[1] <= vah[1]
sellSig = insidePrev and insidePrev2 and close < val and close[1] >= val[1]
touchedPoc = high >= pocPrice and low <= pocPrice and close != pocPrice
touchedPrev = high[1] >= pocPrice[1] and low[1] <= pocPrice[1]
pocAlert = touchedPoc and not touchedPrev

if buySig {
    plotshape(bar_index, low, "Buy", "triangleup", "#22cc88")
    plotshape_3d(bar_index, low, "Buy", "coneup", "#22cc88", 1.0 * markerSize, 1, "3d")
    model.longEntry("BUY")
}
if sellSig {
    plotshape(bar_index, high, "Sell", "triangledown", "#ff4477")
    plotshape_3d(bar_index, high, "Sell", "conedown", "#ff4477", 1.0 * markerSize, 1, "3d")
    model.shortEntry("SELL")
}
if pocAlert {
    plotshape(bar_index, close, "POC", "circle", "#ffd43b")
}

if pocRow != wasPocRow {
    label3d(bar_index, pocPrice, "POC", "#ffd43b", 1.2, 1, "3d")
}
wasPocRow := pocRow * 1.0
pocHold := pocPrice

// ─── 2D: same information when 3D is off ─────────────────────────
plot(pocPrice, "POC", "#ffd43b", 2, "stepline")
plot(vah, "VAH", "#22cc88", 1, "stepline")
plot(val, "VAL", "#ff4477", 1, "stepline")
plot(vaMid, "Value Mid", "#4488ff", 1)
plot(pocShare * close, "POC Share x Price", "#b48cff", 1, "separate")

// Right-anchored histogram bars for row volumes (refresh periodically)
if bar_index % 10 == 0 {
    r = 0
    while r < ProfileRows {
        rv = array.get(rowVol, r)
        w = 0.0
        if pocVol > 0 {
            w := rv / pocVol * 20.0
        }
        rowBot = sessLow + r * rowH
        rowTop = rowBot + rowH
        left = bar_index + 1
        right = bar_index + 1 + floor(w)
        if right < left + 1 {
            right := left + 1
        }
        bcol = "#4488ff"
        if r >= vaBotRow and r <= vaTopRow {
            bcol := "#22cc88"
        }
        if r == pocRow {
            bcol := "#ffd43b"
        }
        box.new(left, rowTop, right, rowBot, bcol, bcol, 1)
        r := r + 1
    }
    text.new(bar_index + 2, pocPrice, "POC", "#ffd43b", 1)
    text.new(bar_index + 2, vah, "VAH", "#22cc88", 1)
    text.new(bar_index + 2, val, "VAL", "#ff4477", 1)
}

if insideVA {
    bgcolor("rgba(34,204,136,0.06)")
} else {
    bgcolor("rgba(255,136,0,0.05)")
}
if touchedPoc {
    bgcolor("rgba(255,212,59,0.08)")
}

// ─── 3D: value terrain + labelled POC rail + boundary rails ──────
terrainCol = "#22cc88"
if not insideVA {
    terrainCol := "#ff8800"
}
plot3d(vaMid, "Value Terrain", "manifold", terrainCol, "3d", 0)
plot3d(pocPrice, "POC Rail", "line3d", "#ffd43b", "3d", 1)
plot3d(vah, "VAH Rail", "line3d", "#22cc88", "3d", 2)

// FIX 1: var lvl = highest(high,20) froze at bar 0 — changed to plain assignment so it recomputes every bar.
// FIX 2: close[-1] peeked one bar into the future — changed to close so the breakout uses only confirmed price.
// FIX 3: plotshape(true,low,"Buy",shape.triangleup,color.green) was Pine signature — changed to OakScript (bar_index,price,title,style,color) with quoted style/color.
// FIX 4: oscillator in price scene fixed — RSI now renders only in 2D, breakout level stays on price chart.
lenHigh = input(20, "High Length", 1, 100, 1)
rsiLen = input(14, "RSI Length", 2, 50, 1)
markerSize = input(1.0, "Marker Size", 0.2, 3.0, 0.1)
lvl = highest(high, lenHigh)
r = rsi(close, rsiLen)
buySig = close > lvl
osSig = crossover(r, 30)
if buySig {
  plotshape(bar_index, low, "Buy", "triangleup", "#22cc88")
}
if osSig {
  plotshape(bar_index, low, "OS", "triangleup", "#22cc88")
}
plot(lvl, "High20", "#ffcc33", 1, "stepline")
plot(r, "RSI", "#b48cff", 1, "line")
